cat > src/claimOffice.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Quote premiums below are final premiums. Unless stated otherwise the customer
// has 0 years with MHPCO and the quote is their first contract, so the policy
// base premium receives only the 10 % first-insurance surcharge and the 5 G fee.
describe("claim office quote", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword -> base 100 G -> premium 115 G");
  it.todo("plain amulet -> base 60 G -> premium 71 G");
  it.todo("plain staff -> base 80 G -> premium 93 G");
  it.todo("plain potion -> base 40 G -> premium 49 G");
  it.todo("one rune -> base 25 G -> 32.5 G rounded up to premium 33 G");
  it.todo("one moonstone -> base 25 G -> premium 33 G");
  it.todo("2 runes -> base 50 G -> premium 60 G");
  it.todo("3 runes -> block base 60 G -> premium 71 G");
  it.todo("4 runes -> base 100 G (block requires exactly 3) -> premium 115 G");
  it.todo("7 runes -> base 175 G -> 197.5 G rounded up to premium 198 G");
  it.todo("2 runes + 1 moonstone -> base 75 G (no block: different types) -> premium 88 G");
  it.todo("3 runes + 3 moonstones -> base 120 G (two separate blocks) -> premium 137 G");
  it.todo("newcomer with cursed steel sword enchantment 3 -> premium 165 G");
  it.todo("cursed sword + plain amulet -> base 160 G + 50 G curse on sword only + 16 G first insurance -> premium 231 G");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge -> premium 145 G");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
  it.todo("cursed sword with exactly enchantment 5 -> both surcharges -> premium 195 G");
  it.todo("cursed sword with enchantment 4 -> only curse surcharge -> premium 165 G");
  it.todo("plain sword + amulet with enchantment 6 -> 30 % of amulet base only -> premium 199 G");
  it.todo("customer with exactly 2 years -> loyalty discount on sword -> premium 95 G");
  it.todo("customer with 1 year -> no loyalty discount on sword -> premium 115 G");
  it.todo("three sword quotes by a newcomer -> 15 % follow-up discount on 2nd and 3rd -> premiums 115, 100, 100 G");
  it.todo("3-year customer's second quote of a cursed steel sword enchantment 7 -> premium 160 G (first insurance still applies)");
});

// Claims reference a policy created by an earlier quote step.
describe("claim office claim", () => {
  it.todo("5-year customer insures silver amulet, fire damages it for 200 G -> premium 59 G, payout 100 G, remaining cap 1100 G");
  it.todo("regular steel sword enchantment 3, damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G");
  it.todo("moonstone, damage 200 G -> payout 100 G, remaining cap 400 G");
  it.todo("staff, damage 500 G -> payout 400 G, remaining cap 1200 G");
  it.todo("potion, damage 500 G -> payout 400 G, remaining cap 400 G");
  it.todo("dragon-material sword exactly enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 G -> payout 700 G, remaining cap 1300 G");
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("steel sword enchantment 8, damage 901 G -> 350.5 G rounded down to payout 350 G, remaining cap 1650 G");
  it.todo("sword + amulet, dragon attack damages sword 500 G and amulet 300 G -> payout 600 G (deductible per item), remaining cap 2600 G");
  it.todo("two swords, both damaged for 500 G -> payout 800 G, remaining cap 3200 G (cap 4000 G)");
  it.todo("cursed sword, damage 1500 G -> payout 1400 G, remaining cap 600 G (cap from unmodified value)");
  it.todo("sword + 3 runes, sword damaged for 500 G -> payout 400 G, remaining cap 3100 G (insurance sum 1750 G)");
  it.todo("sword, two successive claims of 1500 G -> payouts 1400 G then 600 G, remaining cap 600 G then 0 G");
});
EOF
cat > src/cli.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Chosen error contract: the claim-office CLI exits with a non-zero status,
// writes an error description to stderr, and writes nothing to stdout.
describe("claim-office CLI", () => {
  it.todo("schema example on stdin -> stdout {results:[{premium:59},{payout:100,remainingCap:1100}]}, exit 0");
  it.todo("quote with unknown item type broomstick -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim damaging an amulet when only a sword is insured -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim damaging an item of unknown type -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim with two sword damages when only one sword is insured -> non-zero exit, whole claim rejected, no results on stdout");
  it.todo("claim with damage amount -200 -> non-zero exit, error on stderr, no results on stdout");
});
EOF

