export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_TYPES = ["rune", "moonstone"];
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
}

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

function alikeItemsBasePremium(type: string, count: number): number {
  if (isComponent(type) && count === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
  return count * BASE_PREMIUMS[type];
}

function policyBasePremium(items: Item[]): number {
  let sum = 0;
  for (const [type, count] of countByType(items)) sum += alikeItemsBasePremium(type, count);
  return sum;
}

const CURSE_SURCHARGE_PERCENT = 50;

function itemSurcharges(items: Item[]): number {
  return items
    .filter((item) => item.cursed)
    .reduce((sum, item) => sum + (BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_PERCENT) / PERCENT, 0);
}

function premium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const policyPremium =
    (basePremium * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT)) / PERCENT + itemSurcharges(items);
  return Math.ceil(policyPremium + PROCESSING_FEE);
}

export function processScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: premium(step.items) })) };
}

