import { desiredPayout, payoutCap, type Damage } from "./claim.js";
import { quotePremium, type Customer, type Item } from "./premium.js";

export type { Item };

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function processScenario(scenario: Scenario): { results: (QuoteResult | ClaimResult)[] } {
  const remainingCaps = new Map<number, number>();
  let quotesSoFar = 0;
  const results = scenario.steps.map((step, index): QuoteResult | ClaimResult => {
    if (step.op === "quote") {
      remainingCaps.set(index, payoutCap(step.items));
      const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
      quotesSoFar += 1;
